/*
# Exercise Video Guides

1. New Tables
- `exercise_guides` — instructional video links and step-by-step form guides for each exercise
  - `exercise_name` (text, unique) — matches exercise_name in weekly_workouts
  - `video_url` (text) — YouTube search/demonstration link
  - `instructions` (text) — concise form and technique guide
  - `target_muscles` (text) — primary muscle groups worked
  - `difficulty` (text) — beginner/intermediate/advanced

2. Security
- Enable RLS on `exercise_guides`.
- Public readable (anon + authenticated) since programs are public.
- No write policies needed (admin-managed data).

3. Notes
- Video URLs use YouTube search links that are always valid.
- Seeded with all 117 distinct exercises from weekly_workouts.
*/

CREATE TABLE IF NOT EXISTS exercise_guides (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  exercise_name text UNIQUE NOT NULL,
  video_url text NOT NULL,
  instructions text NOT NULL DEFAULT '',
  target_muscles text NOT NULL DEFAULT '',
  difficulty text NOT NULL DEFAULT 'beginner' CHECK (difficulty IN ('beginner','intermediate','advanced')),
  created_at timestamptz DEFAULT now()
);

ALTER TABLE exercise_guides ENABLE ROW LEVEL SECURITY;
GRANT SELECT ON exercise_guides TO anon, authenticated;

DROP POLICY IF EXISTS "read_exercise_guides_public" ON exercise_guides;
CREATE POLICY "read_exercise_guides_public" ON exercise_guides FOR SELECT
TO anon, authenticated USING (true);

CREATE INDEX IF NOT EXISTS idx_exercise_guides_name ON exercise_guides(exercise_name);

-- Seed all exercises
ON CONFLICT (exercise_name) DO NOTHING;
