INSERT INTO exercise_guides (exercise_name, video_url, instructions, target_muscles, difficulty) VALUES
('Barbell Squat', 'https://www.youtube.com/results?search_query=barbell+squat+proper+form+tutorial', 'Stand with feet shoulder-width apart, bar on upper traps. Brace core, break at hips and knees simultaneously, descend until thighs are parallel. Drive through heels to stand.', 'Quads, Glutes, Core', 'beginner'),
('Bench Press', 'https://www.youtube.com/results?search_query=bench+press+proper+form+tutorial', 'Lie flat, eyes under bar, grip slightly wider than shoulders. Retract shoulder blades, lower bar to lower chest, press up and slightly back.', 'Chest, Triceps, Shoulders', 'beginner'),
('Bent-Over Row', 'https://www.youtube.com/results?search_query=bent+over+barbell+row+proper+form', 'Hinge at hips with flat back, bar hanging at arms length. Pull bar to lower ribs, squeeze shoulder blades, lower with control.', 'Back, Biceps, Rear Delts', 'beginner'),
('Deadlift', 'https://www.youtube.com/results?search_query=conventional+deadlift+proper+form+tutorial', 'Bar over mid-foot, feet hip-width. Grip bar, brace core, pull slack out. Drive legs and hips together, lock out at top. Lower with control.', 'Hamstrings, Glutes, Back, Core', 'intermediate'),
('Overhead Press', 'https://www.youtube.com/results?search_query=overhead+barbell+press+proper+form', 'Bar at shoulder height, grip slightly wider than shoulders. Brace core, press bar overhead, finish with bar over mid-foot. Lower to shoulders.', 'Shoulders, Triceps, Upper Chest', 'intermediate'),
('Pull-Ups (assisted)', 'https://www.youtube.com/results?search_query=assisted+pull+ups+proper+form+tutorial', 'Hang from bar with overhand grip. Pull shoulder blades down and back, pull chest toward bar. Lower with control. Use band or machine for assistance.', 'Lats, Biceps, Upper Back', 'beginner'),
('Leg Press', 'https://www.youtube.com/results?search_query=leg+press+machine+proper+form+tutorial', 'Sit in machine, feet shoulder-width on platform. Lower platform until knees reach 90 degrees. Press through heels, dont lock knees.', 'Quads, Glutes, Hamstrings', 'beginner'),
('Dumbbell Shoulder Press', 'https://www.youtube.com/results?search_query=dumbbell+shoulder+press+proper+form', 'Sit or stand with dumbbells at shoulder height. Press overhead until arms are extended. Lower with control to shoulders.', 'Shoulders, Triceps', 'beginner'),
('Plank', 'https://www.youtube.com/results?search_query=plank+proper+form+tutorial', 'Forearms on ground, body in straight line from head to heels. Brace core, squeeze glutes, hold position. Dont let hips sag or rise.', 'Core, Shoulders', 'beginner'),
('Pull-Ups', 'https://www.youtube.com/results?search_query=pull+ups+proper+form+tutorial', 'Hang from bar with overhand grip. Pull shoulder blades down, drive elbows down, pull chin above bar. Lower with full control.', 'Lats, Biceps, Upper Back', 'intermediate'),
('Weighted Pull-Ups', 'https://www.youtube.com/results?search_query=weighted+pull+ups+proper+form', 'Secure weight belt or hold dumbbell between feet. Perform pull-up as normal. Lower with control. Start with 5-10% bodyweight.', 'Lats, Biceps, Upper Back', 'advanced'),
('Bulgarian Split Squat', 'https://www.youtube.com/results?search_query=bulgarian+split+squat+proper+form', 'Rear foot elevated on bench, front foot forward. Lower front thigh to parallel, keep torso upright. Drive through front heel to stand.', 'Quads, Glutes, Core', 'intermediate'),
('Arnold Press', 'https://www.youtube.com/results?search_query=arnold+press+proper+form+tutorial', 'Start with dumbbells in front of shoulders, palms facing you. Press up while rotating palms outward. Reverse on the way down.', 'Shoulders, Triceps', 'intermediate'),
('Hanging Leg Raises', 'https://www.youtube.com/results?search_query=hanging+leg+raises+proper+form', 'Hang from bar, keep legs straight. Raise legs to hip height or higher, engage lower abs. Lower with control, avoid swinging.', 'Core, Hip Flexors', 'intermediate'),
('Pendlay Row', 'https://www.youtube.com/results?search_query=pendlay+row+proper+form+tutorial', 'Bar on floor between reps. Hinge forward with flat back. Explosively pull bar to lower chest, then let it return to floor each rep.', 'Back, Traps, Biceps', 'advanced'),
('Push Press', 'https://www.youtube.com/results?search_query=push+press+proper+form+tutorial', 'Bar at shoulders, dip slightly at knees. Explosively drive up with legs, press bar overhead. Use leg drive to assist the press.', 'Shoulders, Triceps, Legs', 'advanced'),
('Front Squat', 'https://www.youtube.com/results?search_query=front+squat+proper+form+tutorial', 'Bar in front rack position on front delts. Elbows high, torso upright. Squat down, keep chest up. Drive through heels to stand.', 'Quads, Core, Upper Back', 'intermediate'),
('Incline Dumbbell Press', 'https://www.youtube.com/results?search_query=incline+dumbbell+press+proper+form', 'Bench at 30-45 degree incline. Press dumbbells up from chest, slight arc. Lower with control to chest level.', 'Upper Chest, Shoulders', 'beginner'),
('Cable Woodchops', 'https://www.youtube.com/results?search_query=cable+woodchop+proper+form+tutorial', 'Set cable high or low. Stand sideways, rotate torso pulling cable across body. Keep arms relatively straight, drive from core.', 'Core, Obliques', 'beginner'),
('Incline Bench Press', 'https://www.youtube.com/results?search_query=incline+bench+press+proper+form', 'Bench at 30-45 degree incline. Lower bar to upper chest, press up. Grip slightly wider than shoulders.', 'Upper Chest, Shoulders, Triceps', 'beginner'),
('Cable Flyes', 'https://www.youtube.com/results?search_query=cable+flyes+proper+form+tutorial', 'Set cables at chest height. Step forward, bring hands together in arc motion. Squeeze chest at center, return with control.', 'Chest', 'beginner'),
('Tricep Pushdowns', 'https://www.youtube.com/results?search_query=tricep+pushdown+proper+form+tutorial', 'Stand at cable machine, grip bar or rope. Keep elbows tucked, push down until arms fully extended. Squeeze triceps at bottom.', 'Triceps', 'beginner'),
('Lat Pulldown', 'https://www.youtube.com/results?search_query=lat+pulldown+proper+form+tutorial', 'Grip bar wider than shoulders. Pull bar to upper chest, squeeze lats. Control the ascent, dont swing.', 'Lats, Biceps', 'beginner'),
('Barbell Curl', 'https://www.youtube.com/results?search_query=barbell+curl+proper+form+tutorial', 'Stand with bar at arms length, elbows tucked. Curl bar up, squeeze biceps at top. Lower with control, no swinging.', 'Biceps', 'beginner'),
('Leg Extension', 'https://www.youtube.com/results?search_query=leg+extension+proper+form+tutorial', 'Sit in machine, shins under pad. Extend knees fully, squeeze quads. Lower with control. Isolation exercise for quads.', 'Quads', 'beginner'),
('Leg Curl', 'https://www.youtube.com/results?search_query=leg+curl+proper+form+tutorial', 'Lie or sit in machine, pad behind ankles. Curl heels toward glutes, squeeze hamstrings. Lower with control.', 'Hamstrings', 'beginner'),
('Calf Raises', 'https://www.youtube.com/results?search_query=calf+raises+proper+form+tutorial', 'Stand on edge of platform or floor. Rise onto toes, squeeze calves at top. Lower heels below platform for full stretch.', 'Calves', 'beginner'),
('Lateral Raises', 'https://www.youtube.com/results?search_query=lateral+raises+proper+form+tutorial', 'Stand with dumbbells at sides. Raise arms out to sides to shoulder height, slight bend in elbows. Lower with control.', 'Side Delts', 'beginner'),
('Face Pulls', 'https://www.youtube.com/results?search_query=face+pulls+proper+form+tutorial', 'Set cable at face height with rope. Pull rope toward face, external rotate shoulders. Squeeze rear delts at end position.', 'Rear Delts, Rotator Cuff', 'beginner'),
('Shrugs', 'https://www.youtube.com/results?search_query=barbell+shrugs+proper+form+tutorial', 'Hold bar or dumbbells at sides. Shrug shoulders up toward ears, hold briefly. Lower with control. Do not roll shoulders.', 'Traps', 'beginner'),
('Flat Dumbbell Press', 'https://www.youtube.com/results?search_query=flat+dumbbell+press+proper+form', 'Lie flat, dumbbells at chest. Press up until arms extended, dumbbells close together. Lower with control to chest.', 'Chest, Triceps, Shoulders', 'beginner'),
('Incline Flyes', 'https://www.youtube.com/results?search_query=incline+dumbbell+flyes+proper+form', 'Bench at incline, dumbbells above chest with slight bend in elbows. Open arms in wide arc, lower to chest level. Bring back up.', 'Upper Chest', 'intermediate'),
('Overhead Tricep Extension', 'https://www.youtube.com/results?search_query=overhead+tricep+extension+proper+form', 'Hold dumbbell or bar overhead. Lower behind head by bending elbows. Extend back up, keep elbows pointing forward.', 'Triceps', 'beginner'),
('Seated Cable Row', 'https://www.youtube.com/results?search_query=seated+cable+row+proper+form', 'Sit at cable row, feet on pads. Pull handle to lower ribs, squeeze shoulder blades. Return with control, stretch lats.', 'Back, Biceps', 'beginner'),
('Hammer Curls', 'https://www.youtube.com/results?search_query=hammer+curls+proper+form+tutorial', 'Stand with dumbbells, palms facing each other. Curl up keeping palms neutral. Lower with control. Targets brachialis.', 'Biceps, Brachialis, Forearms', 'beginner'),
('Hack Squat', 'https://www.youtube.com/results?search_query=hack+squat+machine+proper+form', 'Position shoulders under pads, feet on platform. Lower until thighs parallel. Press through heels to extend legs.', 'Quads, Glutes', 'intermediate'),
('Romanian Deadlift', 'https://www.youtube.com/results?search_query=romanian+deadlift+proper+form+tutorial', 'Hold bar at hips, slight knee bend. Hinge forward, push hips back, bar slides down legs. Feel hamstring stretch, drive hips forward.', 'Hamstrings, Glutes, Lower Back', 'intermediate'),
('Seated Calf Raises', 'https://www.youtube.com/results?search_query=seated+calf+raises+proper+form', 'Sit in machine, pads on thighs. Rise onto toes, squeeze calves. Lower for full stretch. Targets soleus muscle.', 'Calves (Soleus)', 'beginner'),
('Cable Lateral Raises', 'https://www.youtube.com/results?search_query=cable+lateral+raise+proper+form', 'Stand beside low cable. Raise cable arm out to side to shoulder height. Constant tension from cable. Lower with control.', 'Side Delts', 'beginner'),
('Reverse Pec Deck', 'https://www.youtube.com/results?search_query=reverse+pec+deck+proper+form', 'Sit facing machine, grip handles. Bring arms back in reverse fly motion, squeeze rear delts. Return with control.', 'Rear Delts', 'beginner'),
('Upright Rows', 'https://www.youtube.com/results?search_query=upright+rows+proper+form+tutorial', 'Hold bar at thighs, grip shoulder-width. Pull bar up to chin, elbows leading. Lower with control. Keep bar close to body.', 'Traps, Side Delts', 'intermediate'),
('Barbell Bench Press', 'https://www.youtube.com/results?search_query=barbell+bench+press+proper+form+tutorial', 'Lie flat, grip slightly wider than shoulders. Retract shoulder blades, lower bar to lower chest. Press up explosively.', 'Chest, Triceps, Shoulders', 'intermediate'),
('Dips (weighted)', 'https://www.youtube.com/results?search_query=weighted+dips+proper+form+tutorial', 'Support body on dip bars, lean slightly forward. Lower until shoulders below elbows. Press up. Add weight with belt for resistance.', 'Chest, Triceps', 'advanced'),
('Skull Crushers', 'https://www.youtube.com/results?search_query=skull+crushers+proper+form+tutorial', 'Lie flat, hold bar or dumbbells above forehead. Lower to forehead by bending elbows. Extend back up, keep elbows fixed.', 'Triceps', 'beginner'),
('T-Bar Row', 'https://www.youtube.com/results?search_query=t+bar+row+proper+form+tutorial', 'Straddle T-bar, grip handles. Pull up to chest, squeeze back. Lower with control. Keep back flat, torso at 45 degrees.', 'Back, Lats, Biceps', 'intermediate'),
('Single-Arm Lat Pulldown', 'https://www.youtube.com/results?search_query=single+arm+lat+pulldown+proper+form', 'Use single handle on cable. Pull down to side of chest, squeeze lat. Return with control. Helps address imbalances.', 'Lats, Biceps', 'intermediate'),
('Preacher Curls', 'https://www.youtube.com/results?search_query=preacher+curls+proper+form+tutorial', 'Sit at preacher bench, arms on pad. Curl weight up, squeeze biceps. Lower with control, full extension. Isolates biceps.', 'Biceps', 'beginner'),
('Walking Lunges', 'https://www.youtube.com/results?search_query=walking+lunges+proper+form+tutorial', 'Step forward, lower back knee toward floor. Front knee at 90 degrees. Push through front heel, step forward to next lunge.', 'Quads, Glutes, Hamstrings', 'beginner'),
('Stiff-Leg Deadlift', 'https://www.youtube.com/results?search_query=stiff+leg+deadlift+proper+form', 'Hold bar, keep legs nearly straight. Hinge at hips, lower bar along legs. Feel hamstring stretch. Drive hips forward to stand.', 'Hamstrings, Lower Back', 'intermediate'),
('Standing Calf Raises', 'https://www.youtube.com/results?search_query=standing+calf+raises+proper+form', 'Stand with balls of feet on edge of platform. Rise onto toes, squeeze calves. Lower for full stretch. Targets gastrocnemius.', 'Calves (Gastrocnemius)', 'beginner'),
('Farmer Walks', 'https://www.youtube.com/results?search_query=farmer+walks+proper+form+tutorial', 'Hold heavy dumbbells at sides. Walk with upright posture, core braced. Keep shoulders back. Walk for time or distance.', 'Forearms, Core, Traps', 'beginner'),
('Incline Barbell Press', 'https://www.youtube.com/results?search_query=incline+barbell+press+proper+form', 'Set bench at 30-45 degrees. Lower bar to upper chest, press up. Slightly wider than shoulder grip.', 'Upper Chest, Shoulders, Triceps', 'intermediate'),
('Machine Chest Press', 'https://www.youtube.com/results?search_query=machine+chest+press+proper+form', 'Sit in machine, grip handles at chest height. Press forward until arms extended. Return with control. Fixed path is safer.', 'Chest, Triceps, Shoulders', 'beginner'),
('Rope Pushdowns', 'https://www.youtube.com/results?search_query=rope+tricep+pushdown+proper+form', 'Use rope attachment on high cable. Push down, spread rope at bottom for extra contraction. Keep elbows tucked.', 'Triceps', 'beginner'),
('Deadlift (sumo)', 'https://www.youtube.com/results?search_query=sumo+deadlift+proper+form+tutorial', 'Wide stance, toes pointed out. Grip bar between legs. Drive hips and legs together, lock out. Reduces lower back stress.', 'Glutes, Hamstrings, Quads', 'intermediate'),
('Meadows Row', 'https://www.youtube.com/results?search_query=meadows+row+proper+form+tutorial', 'Use landmine attachment, stand perpendicular. Pull weight up toward hip, squeeze lat. Lower with control. Single-arm row variation.', 'Lats, Upper Back', 'intermediate'),
('Concentration Curls', 'https://www.youtube.com/results?search_query=concentration+curls+proper+form', 'Sit on bench, elbow on inner thigh. Curl dumbbell up, squeeze bicep. Lower with control. Isolation exercise, mind-muscle focus.', 'Biceps', 'beginner'),
('Leg Press (feet high)', 'https://www.youtube.com/results?search_query=leg+press+feet+high+proper+form', 'Place feet higher on platform to target hamstrings and glutes more. Lower platform to 90 degrees. Press through heels.', 'Hamstrings, Glutes', 'intermediate'),
('Glute Ham Raises', 'https://www.youtube.com/results?search_query=glute+ham+raise+proper+form', 'Anchor feet in GHD machine. Lower torso with control, then use hamstrings to pull back up. Excellent posterior chain builder.', 'Hamstrings, Glutes, Lower Back', 'advanced'),
('Donkey Calf Raises', 'https://www.youtube.com/results?search_query=donkey+calf+raises+proper+form', 'Bend at waist, balls of feet on edge of platform. Partner on lower back for weight or use machine. Rise onto toes, lower for stretch.', 'Calves', 'intermediate'),
('Dumbbell Lateral Raises', 'https://www.youtube.com/results?search_query=dumbbell+lateral+raises+proper+form', 'Dumbbells at sides, slight elbow bend. Raise out to shoulder height, palms facing floor. Lower slowly. High volume for delts.', 'Side Delts', 'beginner'),
('Band Pull-Aparts', 'https://www.youtube.com/results?search_query=band+pull+aparts+proper+form', 'Hold resistance band at chest height. Pull band apart, squeeze rear delts and shoulder blades. Return with control.', 'Rear Delts, Upper Back', 'beginner'),
('Barbell Shrugs', 'https://www.youtube.com/results?search_query=barbell+shrugs+heavy+proper+form', 'Hold barbell at thighs. Shrug shoulders up toward ears, hold 1 second. Lower with control. Use heavy weight, dont roll shoulders.', 'Traps', 'beginner'),
('Jumping Jacks', 'https://www.youtube.com/results?search_query=jumping+jacks+proper+form', 'Stand upright, jump feet apart while raising arms overhead. Jump back to start. Full body warm-up and cardio.', 'Full Body, Cardio', 'beginner'),
('Bodyweight Squats', 'https://www.youtube.com/results?search_query=bodyweight+squats+proper+form', 'Stand with feet shoulder-width. Squat down until thighs parallel, keep chest up. Stand through heels. No weight needed.', 'Quads, Glutes', 'beginner'),
('Mountain Climbers', 'https://www.youtube.com/results?search_query=mountain+climbers+proper+form', 'Start in plank position. Drive one knee toward chest, alternate rapidly. Keep core tight, maintain plank position.', 'Core, Cardio, Shoulders', 'beginner'),
('Burpees', 'https://www.youtube.com/results?search_query=burpees+proper+form+tutorial', 'From standing, drop to push-up position. Do a push-up, jump feet to hands, jump up explosively. Full body conditioning.', 'Full Body, Cardio', 'beginner'),
('Kettlebell Swings', 'https://www.youtube.com/results?search_query=kettlebell+swings+proper+form+tutorial', 'Hold kettlebell with both hands. Hinge at hips, swing kettlebell through legs. Drive hips forward explosively to swing up.', 'Glutes, Hamstrings, Core', 'beginner'),
('Plank to Push-Up', 'https://www.youtube.com/results?search_query=plank+to+push+up+proper+form', 'Start in forearm plank. Push up to hand plank one arm at a time. Return to forearms. Keep core tight throughout.', 'Core, Chest, Shoulders', 'beginner'),
('High Knees', 'https://www.youtube.com/results?search_query=high+knees+exercise+proper+form', 'Run in place, drive knees up to hip height. Pump arms. Keep core engaged. Great cardio warm-up or finisher.', 'Cardio, Core, Hip Flexors', 'beginner'),
('Box Jumps', 'https://www.youtube.com/results?search_query=box+jumps+proper+form+tutorial', 'Stand in front of box. Jump onto box, land softly with both feet. Stand up fully. Step down (dont jump down) for safety.', 'Quads, Glutes, Calves', 'beginner'),
('Battle Ropes', 'https://www.youtube.com/results?search_query=battle+ropes+proper+form+tutorial', 'Hold rope ends, create waves by moving arms alternately up and down. Keep core tight, slight squat. High intensity cardio.', 'Shoulders, Arms, Core, Cardio', 'beginner'),
('Jump Rope', 'https://www.youtube.com/results?search_query=jump+rope+proper+form+tutorial', 'Hold rope handles, swing rope overhead. Jump with both feet, small hops. Land on balls of feet. Great cardio and coordination.', 'Calves, Cardio, Coordination', 'beginner'),
('Push-Ups', 'https://www.youtube.com/results?search_query=push+ups+proper+form+tutorial', 'Hands under shoulders, body straight. Lower chest to floor, elbows at 45 degrees. Push up to full extension. Keep core tight.', 'Chest, Triceps, Core', 'beginner'),
('Sprint Intervals (bike)', 'https://www.youtube.com/results?search_query=exercise+bike+sprint+intervals+tutorial', 'Set bike resistance high. Sprint at max effort for 30 seconds. Rest 60 seconds. Repeat. Build power and cardio capacity.', 'Cardio, Legs', 'beginner'),
('Russian Twists', 'https://www.youtube.com/results?search_query=russian+twists+proper+form+tutorial', 'Sit with knees bent, lean back slightly. Hold weight, rotate torso side to side. Keep core engaged, controlled movement.', 'Core, Obliques', 'beginner'),
('Rowing Machine', 'https://www.youtube.com/results?search_query=rowing+machine+proper+form+tutorial', 'Drive with legs first, then pull handle to ribs. Reverse: extend arms, hinge forward, bend knees. Full body cardio.', 'Full Body, Cardio, Back, Legs', 'beginner'),
('Box Step-Ups', 'https://www.youtube.com/results?search_query=box+step+ups+proper+form+tutorial', 'Step onto box with one foot. Drive through that heel to stand on box. Step down with control. Alternate legs.', 'Quads, Glutes', 'beginner'),
('Bicycle Crunches', 'https://www.youtube.com/results?search_query=bicycle+crunches+proper+form+tutorial', 'Lie on back, hands by head. Bring opposite elbow to opposite knee while extending other leg. Alternate in cycling motion.', 'Core, Obliques', 'beginner'),
('Treadmill Sprints', 'https://www.youtube.com/results?search_query=treadmill+sprint+intervals+tutorial', 'Set treadmill to moderate speed. Sprint at high speed for 30 seconds. Step to sides to rest. Repeat for intervals.', 'Cardio, Legs', 'beginner'),
('Goblet Squats', 'https://www.youtube.com/results?search_query=goblet+squat+proper+form+tutorial', 'Hold dumbbell or kettlebell at chest. Squat down, elbows inside knees. Keep chest up. Drive through heels to stand.', 'Quads, Glutes, Core', 'beginner'),
('Thrusters', 'https://www.youtube.com/results?search_query=thrusters+crossfit+proper+form', 'Hold dumbbells at shoulders. Squat down, then explosively stand while pressing dumbbells overhead. Smooth continuous movement.', 'Full Body, Quads, Shoulders', 'intermediate'),
('Rowing Intervals', 'https://www.youtube.com/results?search_query=rowing+intervals+workout+tutorial', 'Row at high intensity for 30 seconds, rest 30 seconds. Focus on powerful leg drive. Repeat for prescribed rounds.', 'Full Body, Cardio', 'intermediate'),
('Kettlebell Snatch', 'https://www.youtube.com/results?search_query=kettlebell+snatch+proper+form', 'Hinge and swing kettlebell between legs. Explosively extend hips, guide kettlebell overhead in one motion. Lock out arm.', 'Full Body, Shoulders, Hips', 'advanced'),
('V-Ups', 'https://www.youtube.com/results?search_query=v+ups+proper+form+tutorial', 'Lie flat, arms overhead. Simultaneously raise legs and torso, touch hands to feet in V position. Lower with control.', 'Core, Hip Flexors', 'intermediate'),
('Sled Push', 'https://www.youtube.com/results?search_query=sled+push+proper+form+tutorial', 'Push weighted sled forward, drive through legs. Keep body at 45-degree angle, long strides. Full body power builder.', 'Quads, Glutes, Calves, Core', 'intermediate'),
('Box Jumps (heightened)', 'https://www.youtube.com/results?search_query=box+jumps+higher+box+proper+form', 'Use higher box than usual. Jump explosively, land softly. Step down. Challenges power and vertical jump capacity.', 'Quads, Glutes, Calves', 'intermediate'),
('Toes to Bar', 'https://www.youtube.com/results?search_query=toes+to+bar+proper+form+tutorial', 'Hang from bar. Raise straight legs until toes touch the bar. Lower with control. Advanced core exercise, requires flexibility.', 'Core, Hip Flexors, Lats', 'advanced'),
('Burpee Broad Jumps', 'https://www.youtube.com/results?search_query=burpee+broad+jump+proper+form', 'Perform burpee, then instead of vertical jump, jump forward as far as possible. Combines conditioning with power.', 'Full Body, Cardio, Legs', 'intermediate'),
('Wall Balls', 'https://www.youtube.com/results?search_query=wall+ball+exercise+proper+form', 'Hold medicine ball, squat down. Explosively stand and throw ball to target on wall. Catch and immediately squat again.', 'Full Body, Quads, Shoulders', 'intermediate'),
('Push-Up to T', 'https://www.youtube.com/results?search_query=push+up+to+T+proper+form', 'Do a push-up, then rotate body to one side, raising arm to ceiling in T position. Alternate sides. Core and shoulder stability.', 'Chest, Core, Shoulders', 'beginner'),
('Assault Bike Sprints', 'https://www.youtube.com/results?search_query=assault+bike+sprint+workout', 'Max effort sprint on assault bike for 20 seconds. Rest 40 seconds. The harder you push, the more resistance it gives.', 'Cardio, Full Body', 'intermediate'),
('Deadlift (high rep)', 'https://www.youtube.com/results?search_query=deadlift+high+rep+light+weight+form', 'Use lighter weight, focus on maintaining form through higher reps. Keep back flat, drive through legs. Great for endurance.', 'Hamstrings, Glutes, Back', 'intermediate'),
('Hanging Windshield Wipers', 'https://www.youtube.com/results?search_query=hanging+windshield+wipers+proper+form', 'Hang from bar, raise legs to parallel. Rotate legs side to side like windshield wipers. Advanced core and stability exercise.', 'Core, Obliques, Shoulders', 'advanced'),
('Stair Climber', 'https://www.youtube.com/results?search_query=stair+climber+machine+workout+tutorial', 'Step on stair climber machine, maintain upright posture. Use moderate pace for steady cardio. Can skip steps for intensity.', 'Cardio, Quads, Glutes, Calves', 'beginner'),
('Jump Squats', 'https://www.youtube.com/results?search_query=jump+squats+proper+form+tutorial', 'Squat down, then jump explosively upward. Land softly back into squat. Immediately repeat. Plyometric power builder.', 'Quads, Glutes, Calves', 'intermediate'),
('Plank Hold', 'https://www.youtube.com/results?search_query=plank+hold+proper+form+tutorial', 'Forearms on ground, body straight line. Brace core and glutes. Hold for prescribed time. Dont let hips sag.', 'Core, Shoulders, Glutes', 'beginner'),
('Power Clean', 'https://www.youtube.com/results?search_query=power+clean+proper+form+tutorial', 'Bar on floor, explosive pull from legs and hips. Catch bar on front shoulders in partial squat. Stand up. Technical Olympic lift.', 'Full Body, Hips, Back, Shoulders', 'advanced'),
('Box Jump (max height)', 'https://www.youtube.com/results?search_query=max+height+box+jump+technique', 'Use maximum height box you can safely jump. Full squat before jumping, drive arms. Land softly. Step down carefully.', 'Quads, Glutes, Calves', 'advanced'),
('Med Ball Slam', 'https://www.youtube.com/results?search_query=medicine+ball+slam+proper+form', 'Hold medicine ball overhead. Explosively slam ball to ground using core. Catch bounce and repeat. Power and stress relief.', 'Core, Shoulders, Back', 'beginner'),
('Back Squat (heavy)', 'https://www.youtube.com/results?search_query=back+squat+heavy+proper+form', 'Bar on upper traps. Brace core hard, maintain tight upper back. Squat with control, drive up powerfully. Heavy strength day.', 'Quads, Glutes, Core', 'intermediate'),
('Nordic Hamstring Curl', 'https://www.youtube.com/results?search_query=nordic+hamstring+curl+proper+form', 'Kneel with feet anchored. Lower torso forward using hamstrings to resist. Catch with hands near floor. Push back up.', 'Hamstrings', 'advanced'),
('Sprint Accelerations', 'https://www.youtube.com/results?search_query=sprint+acceleration+drills+proper+form', 'Start from standing, accelerate to max speed over 40m. Drive arms, lean forward initially, gradually rise to upright.', 'Cardio, Quads, Hamstrings, Glutes', 'intermediate'),
('Lateral Bounds', 'https://www.youtube.com/results?search_query=lateral+bounds+proper+form', 'Jump sideways from one leg to other, stick landing. Explosive lateral power. Keep knee aligned over foot on landing.', 'Glutes, Quads, Hips', 'intermediate'),
('Cone Drills', 'https://www.youtube.com/results?search_query=cone+drills+agility+proper+form', 'Set cones in pattern. Sprint between cones, change direction quickly. Work on acceleration, deceleration, and agility.', 'Cardio, Legs, Agility', 'intermediate'),
('Snatch', 'https://www.youtube.com/results?search_query=barbell+snatch+proper+form+tutorial', 'Bar on floor, explosive full-body pull. Catch bar overhead in full overhead squat position. Stand up. Most technical Olympic lift.', 'Full Body, Hips, Shoulders', 'advanced'),
('Depth Jumps', 'https://www.youtube.com/results?search_query=depth+jumps+proper+form+tutorial', 'Stand on box, step off. Upon landing on floor, immediately jump upward explosively. Advanced plyometric for power.', 'Quads, Glutes, Calves', 'advanced'),
('Rotational Med Ball Throw', 'https://www.youtube.com/results?search_query=rotational+medicine+ball+throw+proper+form', 'Stand sideways to wall. Rotate torso, throw medicine ball against wall powerfully. Catch and repeat. Core rotational power.', 'Core, Obliques, Shoulders', 'intermediate'),
('Front Squat', 'https://www.youtube.com/results?search_query=front+squat+heavy+proper+form', 'Bar in front rack, elbows high. Keep torso as upright as possible. Squat to depth, drive up. Emphasizes quads and core.', 'Quads, Core, Upper Back', 'intermediate'),
('Reverse Lunge (weighted)', 'https://www.youtube.com/results?search_query=reverse+lunge+weighted+proper+form', 'Hold dumbbells or bar. Step backward, lower back knee toward floor. Front knee stays over ankle. Drive through front foot.', 'Quads, Glutes, Hamstrings', 'intermediate'),
('Glute-Ham Raise', 'https://www.youtube.com/results?search_query=glute+ham+raise+machine+proper+form', 'Anchor feet, start upright. Lower body with control, then use hamstrings and glutes to pull back up. Elite posterior chain exercise.', 'Hamstrings, Glutes', 'advanced'),
('Flying Sprints (30m)', 'https://www.youtube.com/results?search_query=flying+sprints+proper+form+tutorial', 'Build up speed over 20m, hit max speed for final 30m. No sharp start—gradual acceleration to top speed. Sprint mechanics.', 'Cardio, Hamstrings, Glutes', 'advanced'),
('Single-Leg Broad Jump', 'https://www.youtube.com/results?search_query=single+leg+broad+jump+proper+form', 'Stand on one leg, jump forward as far as possible. Land on same leg with control. Tests and builds unilateral leg power.', 'Quads, Glutes, Calves', 'advanced'),
('L-Drill', 'https://www.youtube.com/results?search_query=L+drill+agility+proper+form', 'Three cones in L shape. Sprint, change direction around cones. Focus on sharp cuts, staying low. NFL combine agility test.', 'Cardio, Legs, Agility', 'intermediate'),
('Clean and Jerk', 'https://www.youtube.com/results?search_query=clean+and+jerk+proper+form+tutorial', 'Two-part lift: clean bar to shoulders, then jerk overhead. Full body power exercise. Most complex Olympic lift.', 'Full Body, Hips, Shoulders, Legs', 'advanced'),
('Broad Jump', 'https://www.youtube.com/results?search_query=broad+jump+proper+form+tutorial', 'Stand with feet shoulder-width. Squat down, swing arms, jump forward as far as possible. Land softly in squat position.', 'Quads, Glutes, Calves', 'beginner'),
